#!/usr/bin/env bash
# Droit à l'image : rapport des médias en ligne (centre de contrôle) et images de carte.
# Prérequis : apply-docs-tags-pages.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-tags-rapport.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/mediaPeople/router.ts" 2>/dev/null | grep -qF "publicReport: adminProcedure"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "### Les contenus des pages" "apps/web/content/docs/dev/legal/tags-de-personnes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-tags-pages.sh puis apply-docs-tags-pages.sh"; exit 1; }
MODIFIED=("apps/web/src/app/(public)/agenda/page.tsx" "apps/web/src/app/(public)/page.tsx" "apps/web/src/features/app-shell/ControlPanelSidebar.tsx" "packages/backend/src/modules/disciplines/router.ts" "packages/backend/src/modules/events/router.ts" "packages/backend/src/modules/mediaPeople/publicContentRights.service.ts" "packages/backend/src/modules/mediaPeople/router.ts" "packages/backend/src/modules/seminars/router.ts")
CREATED=("apps/web/src/app/(admin)/dashboard/droit-image/page.tsx" "apps/web/src/features/admin/media-people/PublicRightsReport.tsx" "e2e/droit-a-l-image-rapport.spec.ts" "packages/backend/src/modules/mediaPeople/publicRightsReport.service.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "publicReport: adminProcedure" "packages/backend/src/modules/mediaPeople/router.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/app/(admin)/dashboard/droit-image"
