import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
sub('apps/web/src/app/(public)/agenda/page.tsx', 'aW1wb3J0IHsgcGFyc2VQYWdlQ29udGVudFYxIH0gZnJvbSAiQGNvbnRyYWN0cy9wYWdlIjsKaW1wb3J0IHsgcmVzb2x2ZU1lZGlhQnlJZHMgfSBmcm9tICJAYmFja2VuZC9tb2R1bGVzL21lZGlhL3NlcnZpY2VzL3Jlc29sdmVNZWRpYUJ5SWRzLnNlcnZpY2UiOwoKaW1wb3J0IHsgUGFnZVJlbmRlcmVyIH0gZnJvbSAiQGZlYXR1cmVzL3BhZ2UtYnVpbGRlci9QYWdlUmVuZGVyZXIiOwo=',
    '')
